tests_py:
def test_basic():
    assert solution.dot([1, 2, 3], [4, 5, 6]) == 32

def test_single_pair():
    assert solution.dot([2.0], [0.5]) == 1.0

def test_length_mismatch():
    try:
        solution.dot([1, 2], [1])
    except ValueError:
        return
    raise AssertionError("expected ValueError")

def test_empty():
    assert solution.dot([], []) == 0.0

def test_no_mutation():
    a, b = [1, 2], [3, 4]
    solution.dot(a, b)
    assert a == [1, 2] and b == [3, 4]

def test_floats():
    assert abs(solution.dot([0.1, 0.2], [10, 10]) - 3.0) < 1e-9
